:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0e0;
  --accent: #6c63ff;
  --correct: #4caf50;
  --wrong: #f44336;
  --focus: #ffb74d;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  max-width: 40rem;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

h1 {
  margin: 0 0 0.5rem;
  font-size: 1.75rem;
  font-weight: 600;
  color: var(--accent);
}

.instruction {
  margin: 0 0 1.5rem;
  font-size: 1.125rem;
  opacity: 0.9;
}

.sentence {
  font-size: 1.25rem;
  letter-spacing: 0.02em;
  margin-bottom: 1.5rem;
  word-break: break-word;
  min-height: 3rem;
}

.sentence span {
  display: inline;
}

.sentence span.correct {
  color: var(--correct);
  background: rgba(76, 175, 80, 0.15);
  border-radius: 2px;
}

.sentence span.wrong {
  color: var(--wrong);
  background: rgba(244, 67, 54, 0.15);
  border-radius: 2px;
  text-decoration: underline wavy var(--wrong);
}

input {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1.125rem;
  border: 2px solid transparent;
  border-radius: 0.75rem;
  background: #1e1e2f;
  color: var(--text);
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(255, 183, 77, 0.3);
}

input::placeholder {
  color: #888;
}

.result {
  margin-top: 1.5rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.result p {
  margin: 0;
  font-size: 1.25rem;
  font-weight: 500;
}

#accuracy {
  color: var(--accent);
  font-weight: 700;
}

button {
  font: inherit;
  font-size: 1rem;
  padding: 0.6rem 1.5rem;
  border: none;
  border-radius: 0.75rem;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
}

button:hover {
  background: #5a52d5;
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .sentence {
    font-size: 1.125rem;
  }
  .result {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }
  button {
    width: 100%;
  }
}

const targetSentence = "The quick brown fox jumps over the lazy dog.";
const sentenceEl = document.getElementById('sentence');
const inputEl = document.getElementById('input');
const resultEl = document.getElementById('result');
const accuracyEl = document.getElementById('accuracy');
const restartBtn = document.getElementById('restart');

let chars = [];
let correctCount = 0;
let wrongCount = 0;
let finished = false;

function renderSentence() {
  sentenceEl.innerHTML = '';
  chars = targetSentence.split('').map((char) => {
    const span = document.createElement('span');
    span.textContent = char;
    sentenceEl.appendChild(span);
    return span;
  });
}

function updateHighlighting() {
  const typed = inputEl.value;
  correctCount = 0;
  wrongCount = 0;
  for (let i = 0; i < chars.length; i++) {
    const span = chars[i];
    span.classList.remove('correct', 'wrong');
    if (i < typed.length) {
      if (typed[i] === targetSentence[i]) {
        span.classList.add('correct');
        correctCount++;
      } else {
        span.classList.add('wrong');
        wrongCount++;
      }
    }
  }
  if (typed.length >= targetSentence.length) {
    finish();
  }
}

function finish() {
  if (finished) return;
  finished = true;
  const total = targetSentence.length;
  const accuracy = Math.round((correctCount / total) * 100);
  accuracyEl.textContent = accuracy;
  resultEl.hidden = false;
  inputEl.disabled = true;
  restartBtn.focus();
}

function restart() {
  finished = false;
  inputEl.disabled = false;
  inputEl.value = '';
  resultEl.hidden = true;
  accuracyEl.textContent = '0';
  renderSentence();
  inputEl.focus();
}

inputEl.addEventListener('input', () => {
  if (finished) return;
  updateHighlighting();
});

restartBtn.addEventListener('click', restart);

// Initialize
renderSentence();
inputEl.focus();
